// Impératif : comment (boucle + accumulateur mutable)
long total = 0;
for (Order o : orders) if (o.isPaid()) total += o.amount();

// Déclaratif (fonctionnel) : quoi (pipeline pur, immuable)
long total2 = orders.stream()
    .filter(Order::isPaid)
    .mapToLong(Order::amount)
    .sum();

// Réactif : quoi, mais asynchrone et non bloquant (Reactor)
Mono<Long> total3 = orderRepository.findAll()   // Flux<Order>, ne bloque pas
    .filter(Order::isPaid)
    .map(Order::amount)
    .reduce(0L, Long::sum);

// ❌ Impératif : imbrication, l'erreur se gère à chaque niveau
User register(Form f) {
    try {
        Email e = parseEmail(f.email());      // peut lever
        Age a = parseAge(f.age());            // peut lever
        checkNotTaken(e);                     // peut lever
        return save(new User(e, a));
    } catch (ValidationException ex) { /* ... */ }
}

// ✅ Railway : chaque étape renvoie un Result, flatMap court-circuite au 1er échec
Result<User> register(Form f) {
    return parseEmail(f.email())              // Result<Email>
        .flatMap(e -> parseAge(f.age())       // Result<Age>
            .flatMap(a -> checkNotTaken(e)    // Result<Email>
                .map(ok -> new User(e, a))))
        .flatMap(this::save);                 // Result<User>
}
// Côté réactif, l'équivalent est Mono.flatMap + onErrorResume.

// Fonction générale, curryfiée : rate -> (amount -> montant taxé)
Function<Double, Function<Double, Double>> applyTax =
    rate -> amount -> amount * (1 + rate);

// Application partielle : on FIXE le taux → fonctions spécialisées
Function<Double, Double> applyVat      = applyTax.apply(0.20);
Function<Double, Double> applyReduced  = applyTax.apply(0.055);

double ttc = applyVat.apply(100.0);   // 120.0

// Composition : un pipeline nommé, sans classe Strategy
Function<Double, String> priceLabel =
    applyVat.andThen(Math::round).andThen(v -> v + " €");
